controls.onClick:
{() => {
              setSubmitted(true);
              if (canOrder) onOrder({ size: requestedSize, color: color.trim(), option: selectedOption, quantity, customerNote: customerNote.trim(), manualUrl: manualUrl.trim() });
            }}

controls.className:
{`flex h-11 w-11 shrink-0 items-center justify-center rounded-full transition active:scale-90 disabled:pointer-events-none disabled:opacity-35 ${
                isRecording
                  ? 'animate-pulse bg-danger text-white'
                  : surfaceButton
              }`}

{`flex h-11 w-11 shrink-0 items-center justify-center rounded-full border border-line bg-white text-ink shadow-sm transition hover:bg-surface active:scale-90 disabled:pointer-events-none disabled:opacity-35 ${
                  voiceMode ? 'ring-2 ring-white animate-pulse' : ''
                }`}

{`grid h-11 w-11 place-items-center rounded-full transition active:scale-90 ${
            isDark
              ? 'bg-white/10 text-white hover:bg-white/15'
              : 'bg-white text-ink shadow-sm hover:bg-black/5'
          }`}

{`grid h-11 w-11 place-items-center rounded-full transition active:scale-90 ${
            showSettingsModal
              ? 'bg-ink text-white'
              : isDark
                ? 'bg-white/10 text-white hover:bg-white/15'
                : 'bg-white text-ink shadow-sm hover:bg-black/5'
          }`}

{`flex items-center gap-1.5 rounded-full px-3 py-1.5 text-xs font-bold transition active:scale-95 ${
                  isDark
                    ? 'bg-white/10 text-white/90 hover:bg-white/15'
                    : 'bg-white text-ink shadow-sm hover:bg-black/5'
                }`}

{`grid h-12 w-12 place-items-center rounded-full transition active:scale-95 ${
                  attachments && attachments.length > 0
                    ? 'bg-ink text-white shadow-md'
                    : isDark
                      ? 'bg-white/10 text-white hover:bg-white/15'
                      : 'bg-white text-ink shadow-sm hover:bg-black/5'
                }`}

{`grid h-12 w-12 place-items-center rounded-full transition active:scale-95 ${
                  isDark
                    ? 'bg-white/10 text-white hover:bg-white/15'
                    : 'bg-white text-ink shadow-sm hover:bg-black/5'
                }`}

{`grid h-12 w-12 place-items-center rounded-full transition active:scale-95 ${
                  isDark
                    ? 'bg-white/10 text-white hover:bg-white/15'
                    : 'bg-white text-ink shadow-sm hover:bg-black/5'
                }`}

{`grid h-14 w-14 place-items-center rounded-full transition active:scale-95 ${
                isMuted
                  ? 'bg-danger/15 text-danger ring-2 ring-danger/30'
                  : isDark
                    ? 'bg-white/10 text-white hover:bg-white/15'
                    : 'bg-white text-ink shadow-md hover:bg-black/5'
              }`}

{`grid h-14 w-14 place-items-center rounded-full transition active:scale-95 ${
                isSpeakerMuted
                  ? 'bg-white/5 text-muted'
                  : isDark
                    ? 'bg-white/10 text-white hover:bg-white/15'
                    : 'bg-white text-ink shadow-md hover:bg-black/5'
              }`}

{`flex items-center justify-between rounded-2xl p-3.5 text-xs font-bold transition ${
                      selectedVoiceId === 'Aoede'
                        ? 'border-2 border-ink bg-ink/5 text-ink'
                        : isDark
                          ? 'border border-white/10 bg-white/5 text-white'
                          : 'border border-black/5 bg-black/5 text-ink'
                    }`}

{`flex items-center justify-between rounded-2xl p-3.5 text-xs font-bold transition ${
                      selectedVoiceId === 'Kore'
                        ? 'border-2 border-ink bg-ink/5 text-ink'
                        : isDark
                          ? 'border border-white/10 bg-white/5 text-white'
                          : 'border border-black/5 bg-black/5 text-ink'
                    }`}

{`flex items-center justify-between rounded-2xl p-3.5 text-xs font-bold transition ${
                      selectedVoiceId === 'Puck'
                        ? 'border-2 border-ink bg-ink/5 text-ink'
                        : isDark
                          ? 'border border-white/10 bg-white/5 text-white'
                          : 'border border-black/5 bg-black/5 text-ink'
                    }`}

{`flex items-center justify-between rounded-2xl p-3.5 text-xs font-bold transition ${
                      selectedVoiceId === 'Fenrir'
                        ? 'border-2 border-ink bg-ink/5 text-ink'
                        : isDark
                          ? 'border border-white/10 bg-white/5 text-white'
                          : 'border border-black/5 bg-black/5 text-ink'
                    }`}

{`rounded-xl py-2.5 text-xs font-bold transition ${
                        Math.abs(voiceRate - item.val) < 0.04
                          ? 'bg-ink text-white shadow-md'
                          : isDark
                            ? 'bg-white/5 text-white hover:bg-white/10'
                            : 'bg-black/5 text-ink hover:bg-black/10'
                      }`}

controls.onClick:
{() => {
                  if (!available) {
                    setPaymentAvailabilityNotice(method === 'FLOUCI'
                      ? tr('Flouci / D17 reste visible mais désactivé : aucune transaction ne sera simulée sans passerelle réelle.', 'Flouci / D17 ظاهرة لكنها معطلة: لن يتم إنشاء دفع وهمي دون بوابة حقيقية.')
                      : tr('Ce moyen sera activé dès que sa configuration officielle sera disponible.', 'ستُفعّل هذه الوسيلة عند توفر إعداداتها الرسمية.'));
                    return;
                  }
                  setPaymentAvailabilityNotice(''); setError(null);
                  setFormData({ ...formData, paymentMethod: method.toLowerCase() });
                }}

{() => {
                setEmailMode(emailMode === 'login' ? 'register' : 'login');
                setEmailAddress(''); setEmailName('');
                setEmailPassword(''); setShowPassword(false); setRecoveryOpen(false); setError(''); setNotice('');
                document.getElementById('auth-title')?.focus();
              }}

